sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   alert('Thank you for loading the needIt form, click on ok to continue with the form.');

	if (g_form.getValue('priority')==1){
		alert('This is a Priority 1 task, handled it ASAP.');
	}
	else if(g_form.getValue('priority')==4){
		alert('This is a Priority 4 task, handled it accordingly.');
	}

	if(g_form.getValue('priority')==4){
		g_form.showFieldMsg('priority', 'This is a less priority task', 'info');
	}
	g_form.addDecoration('priority', 'icon-star', 'preferred member'); // To add any decoration to already present fields

	if(g_form.isNewRecord()){
		g_form.addInfoMessage('New Record');
	}else{
		g_form.addInfoMessage('Existing Record');
	}

	var currentDescription = g_form.getValue('description');

	g_form.setValue('comments', 'Record Description');

}
